-- WINDOW-RELOCATE-1 + MERGE-SCOPE-PARITY-1 (2026-10-19, charter pillar: autonomy). Breakdown of the 104 failed code_tasks rows of
-- 30 days (2026-10-19 09:10Z): edit-format/SEARCH misses 18, goal-review refusals 15, other 12, suites failing after the edit 11,
-- timeouts 8, verify/publish state 7, reroutes 7, scope refused after the PR 7, whole-file "no file block" 6 (fixed by 0.18.24
-- WHOLE-FILE-PATCH-1, no recurrence after its deploy), syntax 5, standards guard 4, no-progress ceiling 4. Of the 20 failures in the
-- last 20 hours, 8 were SEARCH misses: in every one checked the SEARCH named code that occurs once in the file but outside the
-- anchor window, and 3 were the merge runner refusing a path intake had accepted (personal-companion/wellbeing.js, twice with a PR).
-- qnfo-code-orchestrator 0.18.29 moves the window to a SEARCH that the file holds once (no attempt spent, at most twice per task),
-- and mergeScopeWhy refuses every qnfo-workers path that qnfo-fleet-control cmScope refuses. One detector per cause; both count only
-- tasks created after the fix shipped (2026-10-19T10:00Z), so history does not hold them red.
-- APPLY-BY: ci
-- DB: qnfo-audit
-- Rollback: DELETE FROM remediation_contracts WHERE class IN ('fm-code-task-search-outside-window', 'fm-code-task-scope-late'); DELETE FROM failure_modes WHERE fm_key IN ('code-task-search-outside-window', 'code-task-scope-late')

INSERT OR IGNORE INTO failure_modes (fm_key, failure_mode, root_cause, remediation, detector, probe_class, first_seen, issue_id, trigger_condition, symptom, blast_radius) VALUES
 ('code-task-search-outside-window', 'a code task fails on "SEARCH text occurs 0 times in the shown content" although the file holds that text once, outside the anchor window', 'the anchor window (24k chars) is set once at read; when the model names code elsewhere in the file (a function from the goal) every rung misses and the task burns its attempts', 'qnfo-code-orchestrator 0.18.29 WINDOW-RELOCATE-1: a SEARCH absent from the window and present once in the file moves the window there and runs propose again without spending an attempt (WINDOW_RELOCATE_MAX 2)', 'fm-code-task-search-outside-window: failed tasks created after the fix whose last error is a 0-times SEARCH miss, more than 2 in 24 h', 'fm-code-task-search-outside-window', '2026-10-11T15:10:34Z', NULL, 'a goal that names code far from the anchor', 'code_tasks failed with SEARCH text occurs 0 times in the shown content after 4-6 attempts', 'code loop: 8 of 20 failed tasks from 2026-10-18T13Z to 2026-10-19T09Z'),
 ('code-task-scope-late', 'the merge runner refuses, after the PR is open, a path the code loop accepted at intake', 'mergeScopeWhy checked only <dir>/worker.js and scripts/*; any other qnfo-workers path (a module such as personal-companion/wellbeing.js) passed intake although cmScope never merges it', 'qnfo-code-orchestrator 0.18.29 MERGE-SCOPE-PARITY-1: mergeScopeWhy refuses every qnfo-workers path cmScope refuses (worker.js, docs/**.md, <dir>/README.md and allowed scripts pass), at enqueue and at read', 'fm-code-task-scope-late: tasks created after the fix that ended on outside the auto-merge scope from the merge runner', 'fm-code-task-scope-late', '2026-10-19T07:50:45Z', NULL, 'an issue whose target is a module file in a worker directory', 'a PR is built and opened, then the task fails with merge-runner: path ... is outside the auto-merge scope', 'code loop: model calls and a PR per such task (3 in 24 h)');
INSERT OR IGNORE INTO remediation_contracts (class, issue_id, precondition, action, verify_probe, verify_transport, max_attempts, escalate_to, expected_cadence_h, status, next_due_at, module, budget_ms, max_items, requires_container) VALUES
 ('fm-code-task-search-outside-window', NULL, 'WINDOW-RELOCATE-1', 'failure-mode detector', 'SELECT ''0'' AS expected, CAST((SELECT CASE WHEN COUNT(*) <= 2 THEN 0 ELSE COUNT(*) END FROM code_tasks WHERE status = ''failed'' AND replace(created_at, '' '', ''T'') >= ''2026-10-19T10:00'' AND replace(updated_at, '' '', ''T'') >= strftime(''%Y-%m-%dT%H:%M:%S'', ''now'', ''-24 hours'') AND last_error LIKE ''%occurs 0 times in the shown content%'') AS TEXT) AS observed', 'd1-query', 3, 'qnfo-code-orchestrator', 1, 'active', strftime('%Y-%m-%d %H:%M:%S', 'now'), 'failure-mode', 45000, 5, 0),
 ('fm-code-task-scope-late', NULL, 'MERGE-SCOPE-PARITY-1', 'failure-mode detector', 'SELECT ''0'' AS expected, CAST((SELECT COUNT(*) FROM code_tasks WHERE replace(created_at, '' '', ''T'') >= ''2026-10-19T10:00'' AND last_error LIKE ''merge-runner: path %outside the auto-merge scope%'') AS TEXT) AS observed', 'd1-query', 3, 'qnfo-code-orchestrator', 1, 'active', strftime('%Y-%m-%d %H:%M:%S', 'now'), 'failure-mode', 45000, 5, 0);
